insert overwrite table ${pdm_risk}.pdm_risk_dh_model_final_13collection_call_info_trend_features_di partition(ds='${bizdate}') 
select smp_dt.uid, smp_dt.mdl_dte,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15,atom_dt.talk_duration,null)) as sum_talk_duration_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and call_mode='yuce',1,null)) as count_call_mode_yuce_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and called_phone_social_relations='friend',1,null)) as count_called_phone_social_relations_friend_15d,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and called_phone_social_relations='family',atom_dt.talk_duration,null)) as sum_talk_duration_called_phone_social_relations_family_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and called_phone_social_relations='family',1,null)) as count_called_phone_social_relations_family_15d,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and called_phone_social_relations='friend',atom_dt.talk_duration,null)) as sum_talk_duration_called_phone_social_relations_friend_15d,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and call_mode='ai',atom_dt.talk_duration,null)) as sum_talk_duration_call_mode_ai_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15,1,null)) as count_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and call_mode='ai',1,null)) as count_call_mode_ai_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 15 and is_can_contact_person='yes',1,null)) as count_is_can_contact_person_yes_15d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 180,1,null)) as count_180d,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 180 and called_phone_social_relations='friend',atom_dt.talk_duration,null)) as sum_talk_duration_called_phone_social_relations_friend_180d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 180 and is_can_contact_person='yes',1,null)) as count_is_can_contact_person_yes_180d,
	sum(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 180 and called_phone_social_relations='family',atom_dt.talk_duration,null)) as sum_talk_duration_called_phone_social_relations_family_180d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 180 and call_mode='yuce',1,null)) as count_call_mode_yuce_180d,
