	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 60 and call_mode='yuce' and called_phone_social_relations='friend' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_friend_is_can_contact_person_is_no_60d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 60 and call_mode='yuce' and called_phone_social_relations='friend' and is_can_contact_person='no',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 60) as percent_true_call_mode_is_yuce_called_phone_social_relations_is_friend_is_can_contact_person_is_no_60d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 60 and call_mode='yuce' and called_phone_social_relations='family' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_family_is_can_contact_person_is_no_60d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 7 and call_mode='ai' and called_phone_social_relations='self' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_ai_called_phone_social_relations_is_self_is_can_contact_person_is_no_7d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 7 and call_mode='ai' and called_phone_social_relations='self' and is_can_contact_person='no',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 7) as percent_true_call_mode_is_ai_called_phone_social_relations_is_self_is_can_contact_person_is_no_7d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='ai' and called_phone_social_relations='self' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_ai_called_phone_social_relations_is_self_is_can_contact_person_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='family' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_family_is_can_contact_person_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='ai' and called_phone_social_relations='self' and is_can_contact_person='no',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90) as percent_true_call_mode_is_ai_called_phone_social_relations_is_self_is_can_contact_person_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='friend' and is_can_contact_person='no',1,null)) as num_true_call_mode_is_yuce_called_phone_social_relations_is_friend_is_can_contact_person_is_no_90d,
	count(if(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90 and call_mode='yuce' and called_phone_social_relations='friend' and is_can_contact_person='no',1,null)) / count(datediff(to_date(smp_dt.mdl_dte), to_date(atom_dt.call_time)) <= 90) as percent_true_call_mode_is_yuce_called_phone_social_relations_is_friend_is_can_contact_person_is_no_90d
 
 from （select uid,mdl_dte from pdm_risk.pdm_risk_dh_model_sample_yesterday where ds = '${bizdate}') smp_dt
 left join (select uid,call_time,
case when call_mode = 0 then 'manual' when call_mode = 1 then 'ai'  else 'yuce' end as call_mode,
case when called_phone_social_relations in ('本人','客户本人') then 'self' when called_phone_social_relations in ('家人','子女','兄弟姐妹','父母',
'夫妻','配偶','父亲','母亲') then 'family' else 'friend' end as called_phone_social_relations,
ring_duration,
talk_duration,
case when is_valid_contact =1 then 'yes' else 'no' end as IS_CAN_CONTACT_PERSON,
followup_promise_repay_amount as follow_promise_repay_amount
from dwt.dwt_collection_call_record_detail_di where ds between to_char(date(add_months(to_date('${bizdate}','yyyymmdd'),-6)),'yyyymmdd') and to_char(date(date_add(to_date('${bizdate}','yyyymmdd'),-1)),'yyyymmdd')
and uid is not null and call_time is not null 
) atom_dt
 on smp_dt.uid=atom_dt.uid
and to_date(atom_dt.call_time) >= date_add(to_date(smp_dt.mdl_dte), -180) 
and to_date(atom_dt.call_time) < to_date(smp_dt.mdl_dte)
group by smp_dt.uid, smp_dt.mdl_dte
;
